function activeSoviets(day) {
  return SOVIET_AREAS.filter(function (a) { return day >= a.fromIdx && day <= a.toIdx; });
}

function pointInPolygon(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

    const MESH_COARSE = [80, 58];
    const MESH_MEDIUM = [140, 100];
    const MESH_FINE = [220, 160];


    function buildTerrainMesh(gnx, gny) {
      const verts = [];
      const heights = new Float32Array(gnx * gny);
      const lons = new Float32Array(gnx * gny);
      const lats = new Float32Array(gnx * gny);
      const dLon = (LON1 - LON0) / (gnx - 1);
      const dLat = (LAT1 - LAT0) / (gny - 1);

      for (let j = 0; j < gny; j++) {
        for (let i = 0; i < gnx; i++) {
          const lon = LON0 + i * dLon;
          const lat = LAT0 + j * dLat;
          const hgt = terrainHeight(lon, lat);
          const k = j * gnx + i;
          heights[k] = hgt;
          lons[k] = lon;
          lats[k] = lat;
          verts.push({
            x: (lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: hgt * VSCALE,
            z: -(lat - LAT0) * WORLD_PER_DEG,
            lon: lon,
            lat: lat,
            h: hgt,
            color: null,
            shade: 1,
          });
        }
      }

      if (gnx >= 180) {
        const srcH = heights.slice();
        for (let j = 1; j < gny - 1; j++) {
          for (let i = 1; i < gnx - 1; i++) {
            const k = j * gnx + i;
            heights[k] = (
              srcH[k] * 4 +
              (srcH[k - 1] + srcH[k + 1] + srcH[k - gnx] + srcH[k + gnx]) * 2 +
              srcH[k - gnx - 1] + srcH[k - gnx + 1] + srcH[k + gnx - 1] + srcH[k + gnx + 1]
            ) / 16;
          }
        }
        for (let k = 0; k < heights.length; k++) {
          verts[k].h = heights[k];
          verts[k].y = heights[k] * VSCALE;
        }
      }

      const dxWorld = dLon * COS_REF * WORLD_PER_DEG;
      const dzWorld = dLat * WORLD_PER_DEG;
      for (let j = 0; j < gny; j++) {
        for (let i = 0; i < gnx; i++) {
          const k = j * gnx + i;
          const hW = heights[j * gnx + Math.max(0, i - 1)];
          const hE = heights[j * gnx + Math.min(gnx - 1, i + 1)];
          const hS = heights[Math.max(0, j - 1) * gnx + i];
          const hN = heights[Math.min(gny - 1, j + 1) * gnx + i];
          const dhx = (hE - hW) / (2 * dxWorld);
          const dhz = (hS - hN) / (2 * dzWorld);
          const len = Math.sqrt(dhx * dhx + 1 + dhz * dhz);
          const nx = -dhx / len;
          const ny = 1 / len;
          const nz = -dhz / len;
          const dot = nx * -0.50 + ny * 0.78 + nz * -0.38;
          const dot2 = nx * 0.35 + ny * 0.65 + nz * 0.30;
          const slope = Math.sqrt(dhx * dhx + dhz * dhz);
          const relief = heights[k] - (hW + hE + hS + hN) / 4;
          let shade = 0.54 + Math.max(0, dot) * 0.90 + Math.max(0, dot2) * 0.18;
          shade += clamp(relief / 900, -0.24, 0.28);
          shade *= 0.97 + 0.08 * clamp(heights[k] / 5000, 0, 1);
          shade *= 1 + 0.015 * Math.sin(heights[k] / 110);
          if (heights[k] > 4000) shade = Math.max(shade, 0.78);
          shade = clamp(shade, 0.42, 1.55);
          const col = terrainColor(lons[k], lats[k], heights[k], slope);
          verts[k].color = [
            clamp(col[0] * shade, 0, 255),
            clamp(col[1] * shade, 0, 255),
            clamp(col[2] * shade, 0, 255),
          ];
          verts[k].slope = slope;
          verts[k].shade = shade;
          verts[k].relief = relief;
        }
      }

      if (gnx >= 180) {
        const srcColor = verts.map(function (v) { return v.color; });
        for (let j = 1; j < gny - 1; j++) {
          for (let i = 1; i < gnx - 1; i++) {
            const k = j * gnx + i;
            const c = [0, 0, 0];
            const weights = [4, 2, 2, 2, 2, 1, 1, 1, 1];
            const offsets = [0, -1, 1, -gnx, gnx, -gnx - 1, -gnx + 1, gnx - 1, gnx + 1];
            for (let q = 0; q < 9; q++) {
              const cc = srcColor[k + offsets[q]];
              c[0] += cc[0] * weights[q];
              c[1] += cc[1] * weights[q];
              c[2] += cc[2] * weights[q];
            }
            verts[k].color = [c[0] / 16, c[1] / 16, c[2] / 16];
          }
        }
      }

      const quads = [];
      for (let j = 0; j < gny - 1; j++) {
        for (let i = 0; i < gnx - 1; i++) {
          const a = j * gnx + i;
          const b = a + 1;
          const c = a + gnx + 1;
          const d = a + gnx;
          const col = [
            (verts[a].color[0] + verts[b].color[0] + verts[c].color[0] + verts[d].color[0]) / 4,
            (verts[a].color[1] + verts[b].color[1] + verts[c].color[1] + verts[d].color[1]) / 4,
            (verts[a].color[2] + verts[b].color[2] + verts[c].color[2] + verts[d].color[2]) / 4,
          ];
          quads.push({ a: a, b: b, c: c, d: d, rgb: col, skirt: false });
        }
      }

      const bottomY = -74;
      function addSkirt(topA, topB) {
        quads.push({
          a: topA, b: topB, c: -1, d: -1,
          rgb: [16, 24, 33],
          skirt: true,
          bottomY: bottomY,
        });
      }
      for (let i = 0; i < gnx - 1; i++) addSkirt((0) * gnx + i, (0) * gnx + i + 1);
      for (let i = 0; i < gnx - 1; i++) addSkirt((gny - 1) * gnx + i + 1, (gny - 1) * gnx + i);
      for (let j = 0; j < gny - 1; j++) addSkirt((j + 1) * gnx, j * gnx);
      for (let j = 0; j < gny - 1; j++) addSkirt(j * gnx + gnx - 1, (j + 1) * gnx + gnx - 1);

      return { verts: verts, quads: quads, cols: gnx, rows: gny };
    }

    /* ============================================================
       Projection and scene assembly
       ============================================================ */
    const FOV = 40 * Math.PI / 180;
    const CAM_DIST = 2600;

    function createView(cam, W, H) {
      const rad = Math.PI / 180;
      const cy = Math.cos(cam.yaw * rad);
      const sy = Math.sin(cam.yaw * rad);
      const cp = Math.cos(cam.pitch * rad);
      const sp = Math.sin(cam.pitch * rad);
      const d = CAM_DIST / cam.zoom;
      const f = 0.5 * H / Math.tan(FOV / 2);
      const tx = (cam.lon - LON0) * COS_REF * WORLD_PER_DEG;
      const tz = -(cam.lat - LAT0) * WORLD_PER_DEG;

      function project(x, y, z) {
        const dx = x - tx;
        const dz = z - tz;
        const rx = dx * cy - dz * sy;
        const rz = dx * sy + dz * cy;
        const rely = y - d * sp;
        const relz = rz - d * cp;
        const depth = -rely * sp - relz * cp;
        const upy = rely * cp - relz * sp;
        return {
          x: W / 2 + f * rx / depth,
          y: H / 2 - f * upy / depth,
          depth: depth,
          ok: depth > 24,
        };
      }
      return { project: project, d: d, f: f, cp: cp, sp: sp, cy: cy, sy: sy, tx: tx, tz: tz };
    }

    function hexToRgb(hex) {
      const s = hex.replace('#', '');
      return [
        parseInt(s.slice(0, 2), 16),
        parseInt(s.slice(2, 4), 16),
        parseInt(s.slice(4, 6), 16),
      ];
    }
    function rgba(rgb, a) {
      return 'rgba(' + (rgb[0] | 0) + ',' + (rgb[1] | 0) + ',' + (rgb[2] | 0) + ',' + a + ')';
    }
    function clampByte(v) { return v < 0 ? 0 : v > 255 ? 255 : v; }

    function buildTrail(wps) {
      const out = [];
      for (let i = 1; i < wps.length; i++) {
        const a = wps[i - 1];
        const b = wps[i];
        const dist = Math.sqrt(Math.pow((b.lon - a.lon) * COS_REF, 2) + Math.pow(b.lat - a.lat, 2));
        const n = Math.max(2, Math.ceil(dist / 0.09));
        for (let k = 0; k < n; k++) {
          const t = k / n;
          const lon = lerp(a.lon, b.lon, t);
          const lat = lerp(a.lat, b.lat, t);
          const h = terrainHeight(lon, lat);
          out.push({
            lon: lon, lat: lat, h: h,
            x: (lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: h * VSCALE,
            z: -(lat - LAT0) * WORLD_PER_DEG,
            seg: i - 1, t: t,
          });
        }
      }
      const last = wps[wps.length - 1];
      const lh = terrainHeight(last.lon, last.lat);
      out.push({
        lon: last.lon, lat: last.lat, h: lh,
        x: (last.lon - LON0) * COS_REF * WORLD_PER_DEG,
        y: lh * VSCALE,
        z: -(last.lat - LAT0) * WORLD_PER_DEG,
        seg: wps.length - 1, t: 1,
      });
      return out;
    }

    function clipSegmentToRect(a, b, minLon, maxLon, minLat, maxLat) {
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      let t0 = 0;
      let t1 = 1;
      const p = [-dx, dx, -dy, dy];
      const q = [a[0] - minLon, maxLon - a[0], a[1] - minLat, maxLat - a[1]];
      for (let i = 0; i < 4; i++) {
        if (Math.abs(p[i]) < 1e-12) {
          if (q[i] < 0) return null;
        } else {
          const r = q[i] / p[i];
          if (p[i] < 0) {
            if (r > t1) return null;
            if (r > t0) t0 = r;
          } else {
            if (r < t0) return null;
            if (r < t1) t1 = r;
          }
        }
      }
      if (t1 - t0 < 1e-9) return null;
      return [
        [a[0] + dx * t0, a[1] + dy * t0],
        [a[0] + dx * t1, a[1] + dy * t1],
      ];
    }

    function samePoint(a, b) {
      return Math.abs(a[0] - b[0]) < 1e-7 && Math.abs(a[1] - b[1]) < 1e-7;
    }

    function clipPolylineToRect(points, minLon, maxLon, minLat, maxLat) {
      const out = [];
      let current = [];
      for (let i = 1; i < points.length; i++) {
        const seg = clipSegmentToRect(points[i - 1], points[i], minLon, maxLon, minLat, maxLat);
        if (!seg) {
          if (current.length > 1) out.push(current);
          current = [];
          continue;
        }
        if (current.length === 0) {
          current = [seg[0]];
        } else if (!samePoint(current[current.length - 1], seg[0])) {
          if (current.length > 1) out.push(current);
          current = [seg[0]];
        }
        if (!samePoint(current[current.length - 1], seg[1])) current.push(seg[1]);
      }
      if (current.length > 1) out.push(current);
      return out;
    }

    function buildRiverQuads() {
      const quads = [];
      for (let ri = 0; ri < RIVERS.length; ri++) {
        const river = RIVERS[ri];
        const rgb = hexToRgb(river.rank <= 3 ? river.color : '#4b9fbe');
        const half = Math.max(1.05, river.width * 0.5);
        for (let li = 0; li < river.lines.length; li++) {
          const pieces = clipPolylineToRect(river.lines[li], LON0, LON1, LAT0, LAT1);
          for (let pi = 0; pi < pieces.length; pi++) {
            const line = pieces[pi];
            const pts = [];
            for (let i = 1; i < line.length; i++) {
              const a = line[i - 1];
              const b = line[i];
              const dist = Math.sqrt(Math.pow((b[0] - a[0]) * COS_REF, 2) + Math.pow(b[1] - a[1], 2));
              const n = Math.max(2, Math.ceil(dist / 0.08));
              for (let k = 0; k < n; k++) {
                const t = k / n;
                const lon = lerp(a[0], b[0], t);
                const lat = lerp(a[1], b[1], t);
                const h = terrainHeight(lon, lat);
                pts.push({
                  x: (lon - LON0) * COS_REF * WORLD_PER_DEG,
                  y: h * VSCALE + 3.2,
                  z: -(lat - LAT0) * WORLD_PER_DEG,
                });
              }
            }
            const last = line[line.length - 1];
            const lh = terrainHeight(last[0], last[1]);
            pts.push({
              x: (last[0] - LON0) * COS_REF * WORLD_PER_DEG,
              y: lh * VSCALE + 3.2,
              z: -(last[1] - LAT0) * WORLD_PER_DEG,
            });
            for (let i = 1; i < pts.length; i++) {
              const a = pts[i - 1];
              const b = pts[i];
              const dx = b.x - a.x;
              const dz = b.z - a.z;
              const len = Math.sqrt(dx * dx + dz * dz) || 1;
              const nx = (-dz / len) * half;
              const nz = (dx / len) * half;
              quads.push({
                world: [
                  [a.x + nx, a.y, a.z + nz],
                  [a.x - nx, a.y, a.z - nz],
                  [b.x - nx, b.y, b.z - nz],
                  [b.x + nx, b.y, b.z + nz],
                ],
                rgb: rgb,
                alpha: river.alpha,
                depth: 0,
                river: true,
              });
            }
          }
        }
      }
      return quads;
    }

    function worldPoint(lon, lat, hAdd) {
      const h = terrainHeight(lon, lat);
      return {
        x: (lon - LON0) * COS_REF * WORLD_PER_DEG,
        y: h * VSCALE + (hAdd || 0),
        z: -(lat - LAT0) * WORLD_PER_DEG,
        lon: lon,
        lat: lat,
        h: h,
      };
    }

    function buildProvinceGeometry() {
      return PROVINCE_BOUNDARIES.map(function (p) {
        return {
          name: p.name,
          rings: p.rings.reduce(function (acc, ring) {
            const pieces = clipPolylineToRect(ring, LON0, LON1, LAT0, LAT1);
            for (let i = 0; i < pieces.length; i++) {
              acc.push(pieces[i].map(function (pt) { return worldPoint(pt[0], pt[1], 2.2); }));
            }
            return acc;
          }, []),
        };
      });
    }

    function buildLakeShapes() {
      const all = LAKE_SHAPES.concat(SMALL_LAKES);
      const out = [];
      for (let i = 0; i < all.length; i++) {
        const lake = all[i];
        for (let r = 0; r < lake.rings.length; r++) {
          const ring = lake.rings[r];
          if (!ring || ring.length < 3) continue;
          let maxH = 0;
          const world = ring.map(function (pt) {
            const h = terrainHeight(pt[0], pt[1]);
            if (h > maxH) maxH = h;
            return {
              x: (pt[0] - LON0) * COS_REF * WORLD_PER_DEG,
              y: 0,
              z: -(pt[1] - LAT0) * WORLD_PER_DEG,
            };
          });
          const lakeY = maxH * VSCALE + 2.8;
          for (let k = 0; k < world.length; k++) world[k].y = lakeY;
          out.push({
            name: lake.name,
            world: world,
            rgb: [44, 120, 160],
            line: [146, 214, 240],
            alpha: 0.92,
            kind: 'lake',
          });
        }
      }
      return out;
    }

    function buildSovietCells(area) {
      const poly = area.polygon;
      let minLon = 1e9, maxLon = -1e9, minLat = 1e9, maxLat = -1e9;
      for (let i = 0; i < poly.length; i++) {
        minLon = Math.min(minLon, poly[i][0]);
        maxLon = Math.max(maxLon, poly[i][0]);
        minLat = Math.min(minLat, poly[i][1]);
        maxLat = Math.max(maxLat, poly[i][1]);
      }
      const step = 0.11;
      const half = step * 0.54;
      const cells = [];
      const rgb = hexToRgb(area.color);
      for (let lon = Math.ceil(minLon / step) * step; lon <= maxLon; lon += step) {
        for (let lat = Math.ceil(minLat / step) * step; lat <= maxLat; lat += step) {
          if (!pointInPolygon(lon, lat, poly)) continue;
          const corners = [
            [lon - half, lat - half], [lon + half, lat - half],
            [lon + half, lat + half], [lon - half, lat + half],
          ];
          const world = corners.map(function (c) { return worldPoint(c[0], c[1], 5.0); });
          cells.push({ world: world, rgb: rgb, alpha: 0.08, kind: 'soviet' });
        }
      }
      return cells;
    }

    let SCENE = null;

    function buildScene() {
      if (SCENE) return SCENE;
      const terrainCoarse = buildTerrainMesh(MESH_COARSE[0], MESH_COARSE[1]);
      const terrainMedium = buildTerrainMesh(MESH_MEDIUM[0], MESH_MEDIUM[1]);
      const terrainFine = buildTerrainMesh(MESH_FINE[0], MESH_FINE[1]);
      const riverQuads = buildRiverQuads();
      const forces = {};
      for (let i = 0; i < FORCES.length; i++) {
        const f = FORCES[i];
        forces[f.id] = {
          id: f.id, side: f.side, name: f.name, short: f.short, alias: f.alias,
          color: f.color, rgb: hexToRgb(f.color), commander: f.commander,
          role: f.role, note: f.note, waypoints: f.waypoints, strength: f.strength,
          trail: buildTrail(f.waypoints),
        };
      }
      const events = EVENTS.map(function (e) {
        return Object.assign({}, e, { h: terrainHeight(e.lon, e.lat) });
      });
      const cities = CITY_LABELS.map(function (c) {
        return { name: c[0], lon: c[1], lat: c[2], minZoom: c[3] || 0, h: terrainHeight(c[1], c[2]) };
      });
      const provinces = PROVINCE_LABELS.map(function (c) {
        return { name: c[0], lon: c[1], lat: c[2], h: terrainHeight(c[1], c[2]) };
      });
      const terrainLabels = TERRAIN_LABELS.map(function (c) {
        return { name: c[0], lon: c[1], lat: c[2], kind: c[3], minZoom: c[4] || 0, h: terrainHeight(c[1], c[2]) };
      });
      const peaks = PEAKS.map(function (p) {
        return { name: p[0], elev: p[1], lon: p[2], lat: p[3], h: terrainHeight(p[2], p[3]) };
      });
      const lakeLabels = LAKE_LABELS.map(function (p) {
        return { name: p[0], elev: p[1], lon: p[2], lat: p[3], h: terrainHeight(p[2], p[3]) };
      });
      const riverLabels = RIVER_LABELS.map(function (p) {
        return { name: p[0], lon: p[1], lat: p[2], rank: p[3], h: terrainHeight(p[1], p[2]) };
      });
      const riverGlow = RIVERS.map(function (r) {
        return {
          name: r.name, rank: r.rank,
          lines: r.lines.reduce(function (acc, line) {
            const pieces = clipPolylineToRect(line, LON0, LON1, LAT0, LAT1);
            for (let i = 0; i < pieces.length; i++) {
              acc.push(pieces[i].map(function (pt) { return worldPoint(pt[0], pt[1], 4.2); }));
            }
            return acc;
          }, []),
        };
      });
      const sovietAreas = SOVIET_AREAS.map(function (a) {
        a.rgb = hexToRgb(a.color);
        a.cells = buildSovietCells(a);
        a.borderWorld = a.polygon.map(function (pt) { return worldPoint(pt[0], pt[1], 2.2); });
        a.labelWorld = worldPoint(a.center[0], a.center[1], 4.2);
        return a;
      });
      SCENE = {
        terrainCoarse: terrainCoarse, terrainMedium: terrainMedium, terrainFine: terrainFine,
        riverQuads: riverQuads, forces: forces, events: events,
        cities: cities, provinces: provinces, terrainLabels: terrainLabels,
        provinceGeo: buildProvinceGeometry(),
        lakeShapes: buildLakeShapes(),
        peaks: peaks, lakeLabels: lakeLabels, riverLabels: riverLabels, riverGlow: riverGlow,
        sovietAreas: sovietAreas,
      };
      return SCENE;
    }

    /* ============================================================
       Terrain canvas
       ============================================================ */
    function drawTerrain(canvas, scene, cam, W, H, dpr, day, showSoviet, showRivers, detail) {
      const ctx = canvas.getContext('2d');
      const pw = Math.max(1, Math.floor(W * dpr));
      const ph = Math.max(1, Math.floor(H * dpr));
      if (canvas.width !== pw || canvas.height !== ph) {
        canvas.width = pw;
        canvas.height = ph;
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);

      const view = createView(cam, W, H);
      const mesh = !detail
        ? scene.terrainCoarse
        : (cam.zoom > 0.9 ? scene.terrainFine : scene.terrainMedium);
      const verts = mesh.verts;
      const projected = new Array(verts.length);
      for (let i = 0; i < verts.length; i++) {
        projected[i] = view.project(verts[i].x, verts[i].y, verts[i].z);
      }

      const list = [];
      const quads = mesh.quads;
      for (let q = 0; q < quads.length; q++) {
        const item = quads[q];
        let pts;
        let rgb;
        let kind = 'terrain';
        if (item.skirt) {
          const va = verts[item.a];
          const vb = verts[item.b];
          pts = [
            projected[item.a], projected[item.b],
            view.project(vb.x, item.bottomY, vb.z),
            view.project(va.x, item.bottomY, va.z),
          ];
          rgb = [17, 25, 35];
          kind = 'skirt';
        } else {
          pts = [projected[item.a], projected[item.b], projected[item.c], projected[item.d]];
          rgb = item.rgb;
        }
        let ok = true;
        let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
        let depth = 0;
        for (let k = 0; k < 4; k++) {
          const p = pts[k];
          if (!p.ok) { ok = false; break; }
          if (p.x < minX) minX = p.x;
          if (p.x > maxX) maxX = p.x;
          if (p.y < minY) minY = p.y;
          if (p.y > maxY) maxY = p.y;
          depth += p.depth;
        }
        if (!ok) continue;
        if (maxX < -80 || minX > W + 80 || maxY < -80 || minY > H + 80) continue;
        list.push({ pts: pts, rgb: rgb, depth: depth / 4, kind: kind, alpha: 1 });
      }

      if (showSoviet && cam.zoom > 1.35) {
        const active = activeSoviets(day);
        for (let a = 0; a < active.length; a++) {
          const cells = active[a].cells;
          for (let c = 0; c < cells.length; c++) {
            const item = cells[c];
            const pts = [];
            let depth = 0;
            let ok = true;
            for (let k = 0; k < 4; k++) {
              const wpt = item.world[k];
              const p = view.project(wpt.x, wpt.y, wpt.z);
              if (!p.ok) { ok = false; break; }
              pts.push(p);
              depth += p.depth;
            }
            if (!ok) continue;
            list.push({ pts: pts, rgb: item.rgb, depth: depth / 4, kind: 'soviet', alpha: item.alpha });
          }
        }
      }

      for (let i = 0; i < scene.lakeShapes.length; i++) {
        const lake = scene.lakeShapes[i];
        const pts = [];
        let depth = 1e9;
        let ok = true;
        let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
        for (let k = 0; k < lake.world.length; k++) {
          const wpt = lake.world[k];
          const p = view.project(wpt.x, wpt.y, wpt.z);
          if (!p.ok) { ok = false; break; }
          pts.push(p);
          if (p.depth < depth) depth = p.depth;
          if (p.x < minX) minX = p.x;
          if (p.x > maxX) maxX = p.x;
          if (p.y < minY) minY = p.y;
          if (p.y > maxY) maxY = p.y;
        }
        if (!ok) continue;
        if (maxX < -60 || minX > W + 60 || maxY < -60 || minY > H + 60) continue;
        list.push({
          pts: pts, rgb: lake.rgb, depth: depth - 1,
          kind: 'lake', alpha: lake.alpha, line: lake.line,
        });
      }

      if (showRivers) {
        for (let r = 0; r < scene.riverQuads.length; r++) {
          const item = scene.riverQuads[r];
          const pts = [];
          let depth = 0;
          let ok = true;
          for (let k = 0; k < 4; k++) {
            const wpt = item.world[k];
            const p = view.project(wpt[0], wpt[1], wpt[2]);
            if (!p.ok) { ok = false; break; }
            pts.push(p);
            depth += p.depth;
          }
          if (!ok) continue;
          list.push({ pts: pts, rgb: item.rgb, depth: depth / 4, kind: 'river', alpha: item.alpha });
        }
      }

      list.sort(function (a, b) { return b.depth - a.depth; });

      const bg = ctx.createLinearGradient(0, 0, 0, H);
      bg.addColorStop(0, '#050b14');
      bg.addColorStop(0.55, '#08131f');
      bg.addColorStop(1, '#04080e');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, W, H);

      const glow = ctx.createRadialGradient(W * 0.5, H * 0.44, 40, W * 0.5, H * 0.5, H * 0.8);
      glow.addColorStop(0, 'rgba(48, 96, 124, 0.14)');
      glow.addColorStop(0.6, 'rgba(20, 44, 64, 0.05)');
      glow.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, W, H);

      for (let i = 0; i < list.length; i++) {
        const item = list[i];
        const fog = clamp((item.depth - view.d * 1.02) / (view.d * 1.25), 0, 1) * 0.5;
        const r = clampByte(item.rgb[0] * (1 - fog) + 8 * fog);
        const g = clampByte(item.rgb[1] * (1 - fog) + 15 * fog);
        const b = clampByte(item.rgb[2] * (1 - fog) + 25 * fog);
        const pts = item.pts;

        ctx.beginPath();
        if (item.kind === 'terrain') {
          const cx = (pts[0].x + pts[1].x + pts[2].x + pts[3].x) / 4;
          const cy = (pts[0].y + pts[1].y + pts[2].y + pts[3].y) / 4;
          const e = 1.02;
          ctx.moveTo(cx + (pts[0].x - cx) * e, cy + (pts[0].y - cy) * e);
          for (let k = 1; k < 4; k++) {
            ctx.lineTo(cx + (pts[k].x - cx) * e, cy + (pts[k].y - cy) * e);
          }
        } else {
          ctx.moveTo(pts[0].x, pts[0].y);
          for (let k = 1; k < pts.length; k++) ctx.lineTo(pts[k].x, pts[k].y);
        }
        ctx.closePath();
        ctx.globalAlpha = item.alpha == null ? 1 : item.alpha;
        ctx.fillStyle = 'rgb(' + (r | 0) + ',' + (g | 0) + ',' + (b | 0) + ')';
        ctx.fill();
        if (item.kind === 'lake') {
          ctx.globalAlpha = 0.62;
          ctx.strokeStyle = 'rgb(' + item.line[0] + ',' + item.line[1] + ',' + item.line[2] + ')';
          ctx.lineWidth = 0.9;
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;

      const vig = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.32, W / 2, H / 2, Math.max(W, H) * 0.78);
      vig.addColorStop(0, 'rgba(0,0,0,0)');
      vig.addColorStop(0.72, 'rgba(0,0,0,0.16)');
      vig.addColorStop(1, 'rgba(0,0,0,0.6)');
      ctx.fillStyle = vig;
      ctx.fillRect(0, 0, W, H);
    }

    /* ============================================================
       Overlay drawing helpers
       ============================================================ */
    function createPlacer() {
      const boxes = [];
      return function (x, y, w, h, pad) {
        const p = pad == null ? 3 : pad;
        for (let i = 0; i < boxes.length; i++) {
          const b = boxes[i];
          if (x < b.x + b.w + p && x + w + p > b.x && y < b.y + b.h + p && y + h + p > b.y) return false;
        }
        boxes.push({ x: x, y: y, w: w, h: h });
        return true;
      };
    }

    function roundRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function drawStar(ctx, x, y, r, color, selected, t) {
      ctx.save();
      ctx.translate(x, y);
      if (selected) {
        ctx.beginPath();
        ctx.arc(0, 0, r + 5 + Math.sin(t / 280) * 1.4, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.55)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      ctx.beginPath();
      for (let i = 0; i < 10; i++) {
        const rad = i % 2 === 0 ? r : r * 0.43;
        const a = -Math.PI / 2 + i * Math.PI / 5;
        const px = Math.cos(a) * rad;
        const py = Math.sin(a) * rad;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      ctx.strokeStyle = 'rgba(5,10,18,0.85)';
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.restore();
    }

    function drawDiamond(ctx, x, y, r, color, selected, t) {
      ctx.save();
      ctx.translate(x, y);
      if (selected) {
        ctx.beginPath();
        ctx.arc(0, 0, r + 5 + Math.sin(t / 280) * 1.4, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.moveTo(0, -r);
      ctx.lineTo(r, 0);
      ctx.lineTo(0, r);
      ctx.lineTo(-r, 0);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      ctx.strokeStyle = 'rgba(5,10,18,0.9)';
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.restore();
    }

    function drawArrow(ctx, x, y, angle, color) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      ctx.beginPath();
      ctx.moveTo(7, 0);
      ctx.lineTo(-4, -4.5);
      ctx.lineTo(-2, 0);
      ctx.lineTo(-4, 4.5);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
      ctx.restore();
    }

    function projectWorld(view, p) { return view.project(p.x, p.y, p.z); }

    function strokeTrail(ctx, pts) {
      if (pts.length < 2) return;
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length - 1; i++) {
        const mx = (pts[i].x + pts[i + 1].x) / 2;
        const my = (pts[i].y + pts[i + 1].y) / 2;
        ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
      }
      const last = pts[pts.length - 1];
      ctx.lineTo(last.x, last.y);
    }

    function drawProvinceBorders(ctx, view, scene, cam, W, H) {
      const step = cam.zoom > 1.8 ? 1 : 2;
      ctx.save();
      ctx.setLineDash([2.5, 3.5]);
      ctx.lineWidth = 1;
      ctx.strokeStyle = 'rgba(218,196,158,0.34)';
      for (let p = 0; p < scene.provinceGeo.length; p++) {
        const rings = scene.provinceGeo[p].rings;
        for (let r = 0; r < rings.length; r++) {
          const ring = rings[r];
          ctx.beginPath();
          let started = false;
          let skipped = false;
          for (let i = 0; i < ring.length; i += step) {
            const pt = ring[i];
            const pr = view.project(pt.x, pt.y, pt.z);
            if (!pr.ok || pr.x < -100 || pr.x > W + 100 || pr.y < -100 || pr.y > H + 100) {
              started = false;
              skipped = true;
              continue;
            }
            if (!started) { ctx.moveTo(pr.x, pr.y); started = true; }
            else ctx.lineTo(pr.x, pr.y);
          }
          if (started && !skipped) ctx.closePath();
          ctx.stroke();
        }
      }
      ctx.restore();
    }

    function drawSovietOverlay(ctx, view, scene, day, cam, placer, W, H) {
      const active = activeSoviets(day);
      for (let a = 0; a < active.length; a++) {
        const area = active[a];
        const pts = [];
        let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
        let ok = true;
        const borderWorld = area.borderWorld || area.polygon.map(function (q) { return worldPoint(q[0], q[1], 2.2); });
        for (let i = 0; i < borderWorld.length; i++) {
          const pt = borderWorld[i];
          const pr = view.project(pt.x, pt.y, pt.z);
          if (!pr.ok) { ok = false; break; }
          pts.push(pr);
          if (pr.x < minX) minX = pr.x;
          if (pr.x > maxX) maxX = pr.x;
          if (pr.y < minY) minY = pr.y;
          if (pr.y > maxY) maxY = pr.y;
        }
        if (!ok || pts.length < 3) continue;

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
        ctx.closePath();
        ctx.fillStyle = rgba(area.rgb, 0.13);
        ctx.fill();

        if (cam.zoom > 1.05) {
          ctx.save();
          ctx.clip();
          ctx.strokeStyle = rgba(area.rgb, 0.10);
          ctx.lineWidth = 1;
          ctx.beginPath();
          const span = (maxX - minX) + (maxY - minY);
          for (let d = -span; d < span; d += 9) {
            ctx.moveTo(minX + d, maxY);
            ctx.lineTo(minX + d + (maxY - minY), minY);
          }
          ctx.stroke();
          ctx.restore();
        }

        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
        ctx.closePath();
        ctx.setLineDash([5, 3]);
        ctx.lineWidth = 1.2;
        ctx.strokeStyle = rgba(area.rgb, 0.82);
        ctx.stroke();
        ctx.restore();

        if (cam.zoom < 1.18) continue;
        const cw = area.labelWorld || worldPoint(area.center[0], area.center[1], 4.2);
        const cp = view.project(cw.x, cw.y, cw.z);
        if (cp.ok && cp.x > 40 && cp.x < W - 40 && cp.y > 30 && cp.y < H - 20) {
          ctx.save();
          ctx.font = '600 10px "Noto Sans SC","PingFang SC",sans-serif';
          const tw = ctx.measureText(area.name).width;
          if (placer(cp.x - tw / 2 - 6, cp.y - 9, tw + 12, 18, 3)) {
            ctx.fillStyle = 'rgba(8,15,24,0.72)';
            roundRect(ctx, cp.x - tw / 2 - 6, cp.y - 9, tw + 12, 18, 5);
            ctx.fill();
            ctx.strokeStyle = rgba(area.rgb, 0.55);
            ctx.lineWidth = 0.9;
            ctx.stroke();
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = rgba(area.rgb, 0.98);
            ctx.fillText(area.name, cp.x, cp.y);
          }
          ctx.restore();
        }
      }
    }

    function drawRiversOverlay(ctx, view, scene, cam) {
      ctx.save();
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      for (let i = 0; i < scene.riverGlow.length; i++) {
        const river = scene.riverGlow[i];
        for (let li = 0; li < river.lines.length; li++) {
          const line = river.lines[li];
          ctx.beginPath();
          let started = false;
          for (let k = 0; k < line.length; k++) {
            const pr = view.project(line[k].x, line[k].y, line[k].z);
            if (!pr.ok) { started = false; continue; }
            if (!started) { ctx.moveTo(pr.x, pr.y); started = true; }
            else ctx.lineTo(pr.x, pr.y);
          }
          const alpha = river.rank <= 1 ? 0.38 : river.rank <= 3 ? 0.28 : river.rank <= 4 ? 0.20 : 0.12;
          ctx.strokeStyle = 'rgba(118,216,247,' + alpha + ')';
          ctx.lineWidth = river.rank <= 1 ? 1.8 : river.rank <= 3 ? 1.35 : river.rank <= 4 ? 1.05 : 0.8;
          ctx.shadowColor = 'rgba(80,185,225,0.45)';
          ctx.shadowBlur = river.rank <= 1 ? 6 : river.rank <= 4 ? 3 : 1.5;
          ctx.stroke();
        }
      }
      ctx.restore();
    }

    function drawRiverLabels(ctx, view, scene, cam, placer, W, H) {
      for (let i = 0; i < scene.riverLabels.length; i++) {
        const r = scene.riverLabels[i];
        const minZoom = r.rank <= 2 ? 0.9 : r.rank <= 3 ? 1.15 : r.rank <= 4 ? 1.3 : r.rank <= 5 ? 1.45 : 1.6;
        if (cam.zoom < minZoom) continue;
        const pr = projectWorld(view, {
          x: (r.lon - LON0) * COS_REF * WORLD_PER_DEG,
          y: r.h * VSCALE + 5,
          z: -(r.lat - LAT0) * WORLD_PER_DEG,
        });
        if (!pr.ok || pr.x < 40 || pr.x > W - 40 || pr.y < 24 || pr.y > H - 16) continue;
        const major = r.rank <= 2;
        const mid = r.rank <= 4;
        const fs = major ? 12 : mid ? 10.5 : 9.5;
        ctx.save();
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.font = (major ? '600 ' : mid ? '600 ' : '') + fs + 'px "Noto Sans SC","PingFang SC",sans-serif';
        const tw = ctx.measureText(r.name).width;
        if (!placer(pr.x + 5, pr.y - fs * 0.65, tw, fs + 3, 2)) { ctx.restore(); continue; }
        ctx.fillStyle = 'rgba(3,9,15,0.85)';
        ctx.fillText(r.name, pr.x + 6, pr.y + 1);
        ctx.fillStyle = major ? 'rgba(160,230,255,0.96)' : mid ? 'rgba(135,210,240,0.88)' : 'rgba(120,192,220,0.72)';
        ctx.fillText(r.name, pr.x + 5, pr.y);
        ctx.restore();
      }
    }

    function drawPeaksAndLakes(ctx, view, scene, cam, placer, W, H) {
      const peakAlpha = cam.zoom > 1.35 ? 0.9 : 0.72;
      for (let i = 0; i < scene.peaks.length; i++) {
        const p = scene.peaks[i];
        if (cam.zoom < 1.15 && p.elev < 4800) continue;
        const pr = projectWorld(view, {
          x: (p.lon - LON0) * COS_REF * WORLD_PER_DEG,
          y: p.h * VSCALE + 7,
          z: -(p.lat - LAT0) * WORLD_PER_DEG,
        });
        if (!pr.ok || pr.x < 50 || pr.x > W - 50 || pr.y < 30 || pr.y > H - 20) continue;
        ctx.save();
        ctx.globalAlpha = peakAlpha;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.beginPath();
        ctx.moveTo(pr.x, pr.y - 4);
        ctx.lineTo(pr.x + 3.6, pr.y + 2);
        ctx.lineTo(pr.x - 3.6, pr.y + 2);
        ctx.closePath();
        ctx.fillStyle = 'rgba(236,246,255,0.95)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(8,16,26,0.8)';
        ctx.lineWidth = 0.8;
        ctx.stroke();
        const label = p.name + ' ' + p.elev + 'm';
        ctx.font = '10px "Noto Sans SC","PingFang SC",sans-serif';
        const tw = ctx.measureText(label).width;
        if (placer(pr.x + 5, pr.y - 8, tw, 14, 2)) {
          ctx.fillStyle = 'rgba(4,9,15,0.82)';
          ctx.fillText(label, pr.x + 6, pr.y + 1);
          ctx.fillStyle = 'rgba(224,238,253,0.82)';
          ctx.fillText(label, pr.x + 5, pr.y);
        }
        ctx.restore();
      }

      const showAll = cam.zoom > 1.3;
      for (let i = 0; i < scene.lakeLabels.length; i++) {
        if (!showAll && i >= 4) continue;
        const l = scene.lakeLabels[i];
        const pr = projectWorld(view, {
          x: (l.lon - LON0) * COS_REF * WORLD_PER_DEG,
          y: l.h * VSCALE + 5,
          z: -(l.lat - LAT0) * WORLD_PER_DEG,
        });
        if (!pr.ok || pr.x < 45 || pr.x > W - 45 || pr.y < 26 || pr.y > H - 16) continue;
        const label = l.name + (l.elev ? ' ' + l.elev : '');
        ctx.save();
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.font = '10px "Noto Sans SC","PingFang SC",sans-serif';
        const tw = ctx.measureText(label).width;
        if (placer(pr.x + 5, pr.y - 7, tw, 13, 2)) {
          ctx.beginPath();
          ctx.arc(pr.x, pr.y, 1.6, 0, Math.PI * 2);
          ctx.fillStyle = 'rgba(126,206,238,0.95)';
          ctx.fill();
          ctx.fillStyle = 'rgba(4,10,17,0.82)';
          ctx.fillText(label, pr.x + 6, pr.y + 1);
          ctx.fillStyle = 'rgba(154,220,244,0.85)';
          ctx.fillText(label, pr.x + 5, pr.y);
        }
        ctx.restore();
      }
    }

    /* ============================================================
       Overlay canvas
       ============================================================ */
    function drawOverlay(canvas, scene, state, W, H, dpr) {
      const ctx = canvas.getContext('2d');
      const pw = Math.max(1, Math.floor(W * dpr));
      const ph = Math.max(1, Math.floor(H * dpr));
      if (canvas.width !== pw || canvas.height !== ph) {
        canvas.width = pw;
        canvas.height = ph;
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);

      const cam = state.camera;
      const view = createView(cam, W, H);
      const day = state.day;
      const layers = state.layers;
      const selected = state.selected;
      const now = state.now || 0;
      const hits = [];
      const placer = createPlacer();

      if (layers.provinces) drawProvinceBorders(ctx, view, scene, cam, W, H);
      if (layers.soviet) drawSovietOverlay(ctx, view, scene, day, cam, placer, W, H);
      if (layers.rivers) drawRiversOverlay(ctx, view, scene, cam);

      // Province labels
      if (layers.cities) {
        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '600 12px "Noto Serif SC","Songti SC","STSong",serif';
        for (let i = 0; i < scene.provinces.length; i++) {
          const p = scene.provinces[i];
          const pr = projectWorld(view, {
            x: (p.lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: p.h * VSCALE + 6,
            z: -(p.lat - LAT0) * WORLD_PER_DEG,
          });
          if (!pr.ok || pr.x < 0 || pr.x > W || pr.y < 0 || pr.y > H) continue;
          ctx.fillStyle = 'rgba(230,205,150,0.26)';
          ctx.fillText(p.name, pr.x, pr.y);
        }
        ctx.restore();
      }

      // Terrain feature labels
      if (layers.terrainLabels) {
        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'italic 11px "Noto Serif SC","Songti SC",serif';
        for (let i = 0; i < scene.terrainLabels.length; i++) {
          const p = scene.terrainLabels[i];
          if (cam.zoom < p.minZoom) continue;
          const pr = projectWorld(view, {
            x: (p.lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: p.h * VSCALE + 8,
            z: -(p.lat - LAT0) * WORLD_PER_DEG,
          });
          if (!pr.ok || pr.x < 40 || pr.x > W - 40 || pr.y < 30 || pr.y > H - 20) continue;
          const col = p.kind === 'snow' ? 'rgba(220,238,255,0.72)'
            : p.kind === 'grass' ? 'rgba(214,224,138,0.78)'
            : p.kind === 'ridge' ? 'rgba(205,184,145,0.72)'
            : 'rgba(160,205,165,0.7)';
          ctx.fillStyle = 'rgba(3,8,14,0.75)';
          ctx.fillText(p.name, pr.x + 1, pr.y + 1);
          ctx.fillStyle = col;
          ctx.fillText(p.name, pr.x, pr.y);
        }
        ctx.restore();
      }

      if (layers.terrainLabels) drawPeaksAndLakes(ctx, view, scene, cam, placer, W, H);
      if (layers.rivers) drawRiverLabels(ctx, view, scene, cam, placer, W, H);

      // Cities
      if (layers.cities) {
        ctx.save();
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.font = '11px "Noto Sans SC","PingFang SC","Microsoft YaHei",sans-serif';
        for (let i = 0; i < scene.cities.length; i++) {
          const c = scene.cities[i];
          if (cam.zoom < c.minZoom) continue;
          const pr = projectWorld(view, {
            x: (c.lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: c.h * VSCALE + 4,
            z: -(c.lat - LAT0) * WORLD_PER_DEG,
          });
          if (!pr.ok || pr.x < 10 || pr.x > W - 10 || pr.y < 12 || pr.y > H - 10) continue;
          ctx.beginPath();
          ctx.arc(pr.x, pr.y, 1.8, 0, Math.PI * 2);
          ctx.fillStyle = 'rgba(225,236,248,0.72)';
          ctx.fill();
          const w = ctx.measureText(c.name).width;
          if (placer(pr.x + 5, pr.y - 7, w, 14, 2)) {
            ctx.fillStyle = 'rgba(3,8,14,0.8)';
            ctx.fillText(c.name, pr.x + 6, pr.y + 1);
            ctx.fillStyle = 'rgba(212,224,238,0.72)';
            ctx.fillText(c.name, pr.x + 5, pr.y);
          }
        }
        ctx.restore();
      }

      // Routes
      for (let fi = 0; fi < FORCES.length; fi++) {
        const f = scene.forces[FORCES[fi].id];
        if (!f) continue;
        if (f.side === 'kmt' && !layers.kmt) continue;
        if (f.side === 'red' && !layers.routes) continue;
        const pos = forceAt(f, day);
        const dim = selected && selected !== f.id;
        const alphaMul = selected && selected !== f.id ? 0.45 : 1;

        const full = [];
        for (let i = 0; i < f.trail.length; i += 3) full.push(projectWorld(view, f.trail[i]));
        if (full.length > 1) {
          ctx.save();
          ctx.setLineDash(f.side === 'kmt' ? [5, 6] : [3, 7]);
          ctx.lineWidth = 1.1;
          ctx.strokeStyle = rgba(f.rgb, (f.side === 'kmt' ? 0.24 : 0.22) * alphaMul);
          strokeTrail(ctx, full);
          ctx.stroke();
          ctx.restore();
        }

        const partial = [];
        for (let i = 0; i < f.trail.length; i++) {
          const p = f.trail[i];
          if (p.seg < pos.seg || (p.seg === pos.seg && p.t <= pos.t + 0.0001)) partial.push(projectWorld(view, p));
          else break;
        }
        const curH = terrainHeight(pos.lon, pos.lat);
        partial.push(view.project(
          (pos.lon - LON0) * COS_REF * WORLD_PER_DEG,
          curH * VSCALE + 0.7,
          -(pos.lat - LAT0) * WORLD_PER_DEG
        ));

        if (partial.length > 1) {
          ctx.save();
          ctx.lineJoin = 'round';
          ctx.lineCap = 'round';
          if (f.side === 'kmt') ctx.setLineDash([6, 5]);
          ctx.lineWidth = f.side === 'kmt' ? 1.5 : 2.1;
          ctx.strokeStyle = rgba(f.rgb, (f.side === 'kmt' ? 0.68 : 0.92) * alphaMul);
          ctx.shadowColor = rgba(f.rgb, 0.8 * alphaMul);
          ctx.shadowBlur = f.side === 'kmt' ? 4 : 9;
          strokeTrail(ctx, partial);
          ctx.stroke();
          ctx.restore();

          const p1 = partial[partial.length - 2];
          const p2 = partial[partial.length - 1];
          if (p1 && p2 && Math.hypot(p2.x - p1.x, p2.y - p1.y) > 3) {
            drawArrow(ctx, p2.x, p2.y, Math.atan2(p2.y - p1.y, p2.x - p1.x), rgba(f.rgb, 0.95 * alphaMul));
          }
        }
      }

      // Events
      if (layers.events) {
        const pick = activeEvent(day);
        for (let i = 0; i < scene.events.length; i++) {
          const e = scene.events[i];
          const pr = projectWorld(view, {
            x: (e.lon - LON0) * COS_REF * WORLD_PER_DEG,
            y: e.h * VSCALE + 4.5,
            z: -(e.lat - LAT0) * WORLD_PER_DEG,
          });
          if (!pr.ok || pr.x < 0 || pr.x > W || pr.y < 0 || pr.y > H) continue;
          const isPick = pick.event && pick.event.id === e.id;
          const near = Math.abs(day - e.idx) <= 8;
          const r = isPick ? 5.8 : near ? 4.4 : 3.1;
          const alpha = isPick ? 0.98 : near ? 0.8 : 0.38;
          const col = EVENT_COLORS[e.type] || '#e8c47a';

          if (isPick) {
            ctx.beginPath();
            ctx.arc(pr.x, pr.y, 10 + Math.sin(now / 300) * 2.2, 0, Math.PI * 2);
            ctx.strokeStyle = rgba(hexToRgb(col), 0.45);
            ctx.lineWidth = 1.4;
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(pr.x, pr.y, 16 + Math.sin(now / 300 + 1) * 2.8, 0, Math.PI * 2);
            ctx.strokeStyle = rgba(hexToRgb(col), 0.18);
            ctx.lineWidth = 1;
            ctx.stroke();
          }

          ctx.save();
          ctx.translate(pr.x, pr.y);
          ctx.rotate(Math.PI / 4);
          ctx.globalAlpha = alpha;
          ctx.fillStyle = col;
          ctx.fillRect(-r / 1.4, -r / 1.4, r * 1.42, r * 1.42);
          ctx.strokeStyle = 'rgba(4,9,16,0.9)';
          ctx.lineWidth = 1;
          ctx.strokeRect(-r / 1.4, -r / 1.4, r * 1.42, r * 1.42);
          ctx.restore();

          if (isPick) {
            ctx.save();
            ctx.font = '600 11px "Noto Sans SC","PingFang SC",sans-serif';
            const tw = ctx.measureText(e.title).width;
            const tx = clamp(pr.x - tw / 2, 6, W - tw - 6);
            const ty = pr.y - 24;
            ctx.fillStyle = 'rgba(5,11,19,0.82)';
            roundRect(ctx, tx - 6, ty - 10, tw + 12, 18, 5);
            ctx.fill();
            ctx.strokeStyle = rgba(hexToRgb(col), 0.35);
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.fillStyle = col;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText(e.title, tx, ty);
            ctx.restore();
          }
          hits.push({ type: 'event', id: e.id, x: pr.x, y: pr.y, r: 22 });
        }
      }

      // Forces (columns + markers + labels), far to near
      const forceDraw = [];
      for (let fi = 0; fi < FORCES.length; fi++) {
        const f = scene.forces[FORCES[fi].id];
        if (!f) continue;
        if (f.side === 'kmt' && !layers.kmt) continue;
        const pos = forceAt(f, day);
        const h = terrainHeight(pos.lon, pos.lat);
        const base = view.project(
          (pos.lon - LON0) * COS_REF * WORLD_PER_DEG,
          h * VSCALE,
          -(pos.lat - LAT0) * WORLD_PER_DEG
        );
        forceDraw.push({ f: f, pos: pos, h: h, base: base });
      }
      forceDraw.sort(function (a, b) { return b.base.depth - a.base.depth; });

      for (let i = 0; i < forceDraw.length; i++) {
        const item = forceDraw[i];
        const f = item.f;
        const pos = item.pos;
        const base = item.base;
        if (!base.ok) continue;
        const dim = selected && selected !== f.id;
        const alphaMul = dim ? 0.5 : 1;
        const strength = f.side === 'red' ? strengthAt(f, day) : 0;
        const pinH = 14;
        const pin = view.project(
          (pos.lon - LON0) * COS_REF * WORLD_PER_DEG,
          item.h * VSCALE + pinH,
          -(pos.lat - LAT0) * WORLD_PER_DEG
        );
        if (!pin.ok) continue;

        if (layers.strength && f.side === 'red' && strength > 0.05) {
          const top = view.project(
            (pos.lon - LON0) * COS_REF * WORLD_PER_DEG,
            item.h * VSCALE + 10 + strength * 18,
            -(pos.lat - LAT0) * WORLD_PER_DEG
          );
          if (top.ok) {
            const grad = ctx.createLinearGradient(base.x, base.y, top.x, top.y);
            grad.addColorStop(0, rgba(f.rgb, 0.05));
            grad.addColorStop(0.30, rgba(f.rgb, 0.30));
            grad.addColorStop(1, rgba(f.rgb, 0.82));
            const bw = 14;
            const tw = 8;
            ctx.save();
            ctx.globalAlpha = 0.95 * alphaMul;
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(base.x - bw / 2, base.y);
            ctx.lineTo(top.x - tw / 2, top.y);
            ctx.lineTo(top.x + tw / 2, top.y);
            ctx.lineTo(base.x + bw / 2, base.y);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = rgba(f.rgb, 0.45);
            ctx.lineWidth = 0.8;
            ctx.stroke();
            ctx.beginPath();
            ctx.ellipse(top.x, top.y, tw * 0.9, 3.1, 0, 0, Math.PI * 2);
            ctx.fillStyle = rgba(f.rgb, 0.98);
            ctx.fill();
            ctx.beginPath();
            ctx.ellipse(top.x, top.y, tw * 0.9, 3.1, 0, 0, Math.PI * 2);
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 0.7;
            ctx.stroke();
            ctx.restore();

            ctx.save();
            ctx.font = '700 11px "DIN Alternate","Bahnschrift","Noto Sans SC",sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'bottom';
            ctx.fillStyle = rgba(f.rgb, 0.95 * alphaMul);
            ctx.shadowColor = 'rgba(0,0,0,0.8)';
            ctx.shadowBlur = 4;
            ctx.fillText(strength.toFixed(1) + '万', top.x, top.y - 4);
            ctx.restore();
          }
        }

        ctx.save();
        ctx.globalAlpha = alphaMul;
        ctx.beginPath();
        ctx.moveTo(base.x, base.y);
        ctx.lineTo(pin.x, pin.y);
        ctx.strokeStyle = rgba(f.rgb, 0.72);
        ctx.lineWidth = 1.2;
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(base.x, base.y, 2.4, 0, Math.PI * 2);
        ctx.fillStyle = rgba(f.rgb, 0.8);
        ctx.fill();
        ctx.restore();

        const isSel = selected === f.id;
        if (f.side === 'red') drawStar(ctx, pin.x, pin.y, isSel ? 8.5 : 7, f.color, isSel, state.now);
        else drawDiamond(ctx, pin.x, pin.y, isSel ? 7 : 5.8, f.color, isSel, state.now);

        const label = f.side === 'red'
          ? f.short + ' ' + strength.toFixed(1) + '万'
          : f.name;
        const sub = f.side === 'red' ? pos.status : pos.status;
        ctx.save();
        ctx.font = '600 11px "Noto Sans SC","PingFang SC",sans-serif';
        const lw = ctx.measureText(label).width;
        ctx.font = '10px "Noto Sans SC","PingFang SC",sans-serif';
        const sw = ctx.measureText(sub || '').width;
        const boxW = Math.max(lw, sw) + 12;
        const dirs = [[11, -10], [11, 4], [-boxW - 11, -10], [11, -26], [-boxW - 11, 4], [11, 18]];
        let placed = false;
        for (let d = 0; d < dirs.length; d++) {
          const bx = pin.x + dirs[d][0];
          const by = pin.y + dirs[d][1];
          if (placer(bx, by, boxW, 30, 3)) {
            ctx.globalAlpha = alphaMul;
            ctx.fillStyle = 'rgba(5,11,19,0.72)';
            roundRect(ctx, bx, by, boxW, 30, 5);
            ctx.fill();
            ctx.strokeStyle = rgba(f.rgb, 0.28);
            ctx.lineWidth = 0.8;
            ctx.stroke();
            ctx.textAlign = 'left';
            ctx.textBaseline = 'top';
            ctx.font = '600 11px "Noto Sans SC","PingFang SC",sans-serif';
            ctx.fillStyle = f.side === 'red' ? 'rgba(255,240,235,0.96)' : 'rgba(226,238,252,0.92)';
            ctx.fillText(label, bx + 6, by + 4);
            ctx.font = '10px "Noto Sans SC","PingFang SC",sans-serif';
            ctx.fillStyle = 'rgba(160,180,200,0.9)';
            ctx.fillText(sub || f.role, bx + 6, by + 17);
            placed = true;
            break;
          }
        }
        ctx.restore();

        hits.push({ type: 'force', id: f.id, x: pin.x, y: pin.y, r: 15 });
      }

      // Compass
      const cx = 42;
      const cy = H - 42;
      ctx.save();
      ctx.translate(cx, cy);
      ctx.beginPath();
      ctx.arc(0, 0, 21, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(5,11,19,0.55)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(210,180,120,0.28)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.rotate(cam.yaw * Math.PI / 180);
      ctx.beginPath();
      ctx.moveTo(0, -14);
      ctx.lineTo(4.5, 6);
      ctx.lineTo(0, 3);
      ctx.lineTo(-4.5, 6);
      ctx.closePath();
      ctx.fillStyle = 'rgba(232,196,122,0.9)';
      ctx.fill();
      ctx.font = '600 9px "Noto Sans SC",sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'rgba(232,196,122,0.85)';
      ctx.fillText('北', 0, -20);
      ctx.restore();

      // Scale bar (approx. 200 km at the target latitude)
      const kmPerDeg = 111;
      const deg = 200 / kmPerDeg;
      const pA = view.project(
        (cam.lon - LON0) * COS_REF * WORLD_PER_DEG,
        terrainHeight(cam.lon, cam.lat) * VSCALE,
        -(cam.lat - LAT0) * WORLD_PER_DEG
      );
      const pB = view.project(
        (cam.lon + deg - LON0) * COS_REF * WORLD_PER_DEG,
        terrainHeight(cam.lon + deg, cam.lat) * VSCALE,
        -(cam.lat - LAT0) * WORLD_PER_DEG
      );
      const barW = clamp(Math.abs(pB.x - pA.x), 40, 140);
      const sx = W - barW - 28;
      const sy = H - 26;
      ctx.save();
      ctx.strokeStyle = 'rgba(216,228,240,0.55)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(sx + barW, sy);
      ctx.moveTo(sx, sy - 4);
      ctx.lineTo(sx, sy + 4);
      ctx.moveTo(sx + barW, sy - 4);
      ctx.lineTo(sx + barW, sy + 4);
      ctx.stroke();
      ctx.font = '10px "Noto Sans SC",sans-serif';
      ctx.fillStyle = 'rgba(200,215,230,0.7)';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'bottom';
      ctx.fillText('约 200 km', sx + barW / 2, sy - 5);
      ctx.restore();

      // Hover tooltip
      if (state.hovered) {
        const hit = state.hovered;
        let title = '';
        let lines = [];
        if (hit.type === 'force') {
          const f = scene.forces[hit.id];
          const pos = forceAt(f, day);
          title = f.name + (f.alias ? ' · ' + f.alias : '');
          if (f.side === 'red') {
            lines = ['兵力 约' + strengthAt(f, day).toFixed(1) + '万', '状态 ' + (pos.status || f.role)];
          } else {
            lines = [f.commander, '状态 ' + (pos.status || f.role)];
          }
        } else {
          const e = scene.events.filter(function (x) { return x.id === hit.id; })[0];
          if (e) {
            title = e.title;
            lines = [e.place, fmtFull(e.idx), e.people];
          }
        }
        if (title) {
          ctx.save();
          ctx.font = '600 12px "Noto Sans SC",sans-serif';
          const tw = ctx.measureText(title).width;
          ctx.font = '10px "Noto Sans SC",sans-serif';
          let mw = tw;
          for (let i = 0; i < lines.length; i++) mw = Math.max(mw, ctx.measureText(lines[i]).width);
          const bw = mw + 20;
          const bh = 24 + lines.length * 14;
          const bx = clamp(hit.x + 16, 8, W - bw - 8);
          const by = clamp(hit.y - bh - 8, 8, H - bh - 8);
          ctx.fillStyle = 'rgba(6,13,22,0.94)';
          roundRect(ctx, bx, by, bw, bh, 7);
          ctx.fill();
          ctx.strokeStyle = 'rgba(232,196,122,0.35)';
          ctx.lineWidth = 1;
          ctx.stroke();
          ctx.textAlign = 'left';
          ctx.textBaseline = 'top';
          ctx.fillStyle = '#f2e6cf';
          ctx.font = '600 12px "Noto Sans SC",sans-serif';
          ctx.fillText(title, bx + 10, by + 6);
          ctx.font = '10px "Noto Sans SC",sans-serif';
          ctx.fillStyle = 'rgba(178,196,214,0.9)';
          for (let i = 0; i < lines.length; i++) ctx.fillText(lines[i], bx + 10, by + 24 + i * 14);
          ctx.restore();
        }
      }

      state.hitRef = hits;
    }

    /* ============================================================
       Store (shared by the composer launcher and the full-screen atlas)
       ============================================================ */
    const storeListeners = new Set();
    let storeOpen = typeof location !== 'undefined' && /long-march-atlas/.test(location.hash || '');

    function subscribeStore(cb) {
      storeListeners.add(cb);
      return function () { storeListeners.delete(cb); };
    }
    function getOpen() { return storeOpen; }
    function setOpen(v) {
      if (storeOpen === v) return;
      storeOpen = v;
      storeListeners.forEach(function (cb) { cb(); });
    }
    function useOpen() {
      return useSyncExternalStore(subscribeStore, getOpen, getOpen);
    }

